import json

def complete_sequence(s):
    pairs = {')': '(', ']': '[', '}': '{', '>': '<'}
    openers = set(pairs.values())
    stack = []
    for tok in s.split():
        if tok in openers:
            stack.append(tok)
        elif tok in pairs:
            if not stack or stack[-1] != pairs[tok]:
                return None, {"error": "mismatch", "token": tok, "depth": len(stack)}
            stack.pop()
        else:
            return None, {"error": "invalid_token", "token": tok}
    closer = {v: k for k, v in pairs.items()}
    completion = ''.join(closer[o] for o in reversed(stack))
    return completion, {"open_stack_bottom_to_top": stack, "unmatched_count": len(stack)}

src = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"

result, info = complete_sequence(src)
if result is None:
    final = "UNSUPPORTED"
else:
    final = result

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "tokens": len(src.split()),
        "method": "stack matching over (), [], {}, <>",
        **info
    }
}, separators=(",", ":")))
