import json

def complete_brackets(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())
    stack = []
    for ch in s:
        if ch in openers:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return None, "mismatched closer: " + ch
            stack.pop()
    closer_of = {'(': ')', '[': ']', '{': '}'}
    completion = ''.join(closer_of[c] for c in reversed(stack))
    return completion, "open stack (bottom->top): " + ''.join(stack)

source = "{ [ [ ] [ ]"
completion, note = complete_brackets(source)

if completion is None:
    result = {"final_answer": "UNSUPPORTED", "evidence": {"input": source, "note": note}}
else:
    result = {
        "final_answer": completion,
        "evidence": {
            "input": source,
            "note": note,
            "full_sequence": source + " " + " ".join(completion)
        }
    }

print(json.dumps(result, separators=(",", ":")))
