def run_check():
    openers = {'(': ')', '[': ']', '{': '}'}
    closers = {')': '(', ']': '[', '}': '{'}

    def apply_tokens(stack, tokens):
        # Returns the resulting stack, or None if a closer mismatches.
        stack = list(stack)
        for tok in tokens:
            if tok in openers:
                stack.append(tok)
            elif tok in closers:
                if not stack or stack[-1] != closers[tok]:
                    return None
                stack.pop()
            else:
                return None
        return stack

    prompt = "{ [ [ ] [ ]".split()
    submitted = "] ]".split()

    # Exact state after the given prefix.
    prefix_stack = apply_tokens([], prompt)
    print("prefix valid:", prefix_stack is not None)
    print("open stack after prefix:", " ".join(prefix_stack))

    # Unique minimal completion: close the open stack in reverse order.
    expected = [openers[c] for c in reversed(prefix_stack)]
    print("expected completion:", " ".join(expected))

    # Check the submitted answer: it must be valid and leave the stack empty.
    after_submit = apply_tokens(prefix_stack, submitted)
    if after_submit is None:
        print("submitted completion is invalid: a closer does not match the open bracket")
        print("submitted answer:", " ".join(submitted))
        print("CHECK FAIL")
    elif after_submit == []:
        print("submitted completion balances the sequence")
        print("CHECK PASS")
    else:
        print("submitted completion leaves unclosed:", " ".join(after_submit))
        print("CHECK FAIL")


if __name__ == "__main__":
    run_check()
