import json
from fractions import Fraction

S = Fraction(1070)   # sum of all interior angles except one, in degrees
candidates = []

# Convex polygon with n sides: interior angles sum to (n-2)*180 and each lies in (0, 180).
# Missing angle x = (n-2)*180 - 1070 must satisfy 0 < x < 180.
# The remaining n-1 angles sum to 1070 and each must lie in (0, 180),
# so 0 < 1070 < 180*(n-1) must hold.
for n in range(3, 1001):
    total = Fraction(180 * (n - 2))
    x = total - S
    if not (0 < x < 180):
        continue
    if not (0 < S < 180 * (n - 1)):
        continue
    candidates.append({
        "n": n,
        "missing_angle_deg": str(x),
        "avg_remaining_deg": str(S / (n - 1)),
    })

if len(candidates) == 1:
    final_answer = str(candidates[0]["n"])
else:
    final_answer = "UNSUPPORTED"

result = {
    "final_answer": final_answer,
    "evidence": {
        "given_partial_sum_deg": str(S),
        "feasible_candidates": candidates,
        "method": "exhaustive enumeration n in [3,1000] with 0<missing<180 and convexity bound on remaining angles",
    },
}
print(json.dumps(result, separators=(",", ":")))
