import json
import math
from fractions import Fraction as Fr

# Reduce with t = cos 2x: cos x(cos x - cos 5x) = 1 + 2t - t^2 - 2t^3 (exact identity).
def rhs_t(t):
    return (1 + t - (2 * t * t - 1) - (4 * t ** 3 - 3 * t)) / 2

def lhs_t(t):
    return (Fr(7, 4) - 2 * t) * abs(2 * t + 1)

def g_exact(t):
    return lhs_t(t) - rhs_t(t)

def g_float(t):
    return (7 / 4 - 2 * t) * abs(2 * t + 1) - (1 + t - (2 * t * t - 1) - (4 * t ** 3 - 3 * t)) / 2

# 1) Exact rational roots of g on t in [-1, 1]
exact_roots = set()
for q in range(1, 9):
    for p in range(-q, q + 1):
        t = Fr(p, q)
        if g_exact(t) == 0:
            exact_roots.add(t)

# 2) Sign-change scan on [-1, 1] for any irrational roots, refined by bisection
approx_roots = []
N = 40000
prev_t = -1.0
prev_v = g_float(prev_t)
for i in range(1, N + 1):
    t = -1.0 + 2.0 * i / N
    v = g_float(t)
    if prev_v * v < 0:
        lo, hi = prev_t, t
        for _ in range(100):
            mid = (lo + hi) / 2
            if g_float(lo) * g_float(mid) <= 0:
                hi = mid
            else:
                lo = mid
        approx_roots.append((lo + hi) / 2)
    prev_t, prev_v = t, v

# 3) Map each valid t = cos 2x to x mod pi (exact in units of pi)
residues = set()
for t in list(exact_roots) + approx_roots:
    tf = float(t)
    if abs(tf) > 1:
        continue
    x0 = math.acos(max(-1.0, min(1.0, tf))) / 2
    for x in (x0, -x0):
        r = Fr(x / math.pi).limit_denominator(100) % 1
        residues.add(r)

residues = sorted(residues)

# 4) Verify against the original equation directly in x
def f_orig(x):
    c2 = math.cos(2 * x)
    return (1.75 - 2 * c2) * abs(2 * c2 + 1) - math.cos(x) * (math.cos(x) - math.cos(5 * x))

max_resid = 0.0
solutions_0_2pi = 0
for r in residues:
    for k in (0, 1):
        x = (float(r) + k) * math.pi
        if 0 <= x < 2 * math.pi:
            max_resid = max(max_resid, abs(f_orig(x)))
            solutions_0_2pi += 1

# Grid sign-change count of the original residual on [0, 2pi)
M = 200000
vals = [f_orig(2 * math.pi * i / M) for i in range(M)]
sign_changes = sum(1 for i in range(M) if vals[i] * vals[(i + 1) % M] < 0)

pieces = []
for r in residues:
    n, d = r.numerator, r.denominator
    pieces.append(f"π/{d}" if n == 1 else f"{n}π/{d}")

final_answer = "x = " + " or ".join(f"{p} + kπ" for p in pieces) + ", k ∈ ℤ"

result = {
    "final_answer": final_answer,
    "evidence": {
        "reduction": "t=cos2x; RHS=1+2t-t^2-2t^3; cases on sign of 2t+1",
        "exact_t_roots": sorted(str(t) for t in exact_roots),
        "approx_t_roots": [round(t, 10) for t in approx_roots],
        "residues_mod_pi": [str(r) for r in residues],
        "solutions_in_0_2pi": solutions_0_2pi,
        "max_abs_residual_at_candidates": max_resid,
        "grid_sign_changes_0_2pi": sign_changes,
    },
}

print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))
